const drive = $json;
const allowed = new Set([
  'application/pdf',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/vnd.openxmlformats-officedocument.presentationml.presentation',
  'application/vnd.google-apps.spreadsheet'
]);
const mimeType = drive.mimeType || drive.mime_type;
if (!allowed.has(mimeType)) throw new Error(`UNSUPPORTED_FILE_TYPE: ${mimeType}`);
const fileId = drive.id || drive.file_id;
const fileName = drive.name || drive.file_name;
const sourceHash = drive.md5Checksum || drive.sha256Checksum || `${fileId}:${drive.modifiedTime || drive.version || ''}`;
if (!fileId || !fileName || !sourceHash) throw new Error('INVALID_DRIVE_METADATA');
return [{json:{file_id:fileId,file_name:fileName,mime_type:mimeType,source_url:drive.webViewLink || (mimeType === 'application/vnd.google-apps.spreadsheet' ? `https://docs.google.com/spreadsheets/d/${fileId}/edit` : `https://drive.google.com/file/d/${fileId}/view`),source_hash:String(sourceHash),product_code:'ENJICAD',knowledge_base_code:'KB_PRODUCT_ENJICAD',language_code:'vi'}}];

const meta = $('Prepare Source Metadata1').item.json;
const response = $json || {};

const payload =
  response.data &&
  typeof response.data === 'object' &&
  !Array.isArray(response.data)
    ? response.data
    : response;


// ==============================
// EXTRACT TEXT
// ==============================
function extractText(obj) {
  if (!obj || typeof obj !== 'object') return '';

  // 1. Các parser cũ
  const direct =
    obj.markdown ??
    obj.text ??
    obj.content ??
    obj.result;

  if (typeof direct === 'string' && direct.trim()) {
    return direct;
  }

  // 2. response.data là string
  if (typeof obj.data === 'string' && obj.data.trim()) {
    return obj.data;
  }

  // 3. Gemini generateContent
  if (Array.isArray(obj.candidates)) {
    const texts = [];

    for (const candidate of obj.candidates) {
      const parts = candidate?.content?.parts;

      if (!Array.isArray(parts)) continue;

      for (const part of parts) {
        // Không lấy thinking/reasoning nếu model trả về
        if (part?.thought === true) continue;

        if (typeof part?.text === 'string' && part.text.trim()) {
          texts.push(part.text);
        }
      }
    }

    return texts.join('\n');
  }

  return '';
}


let raw = extractText(payload);

// fallback nếu data wrapper không chứa text
if (!raw && payload !== response) {
  raw = extractText(response);
}

raw = String(raw || '').trim();

const finishReasons = Array.isArray(payload?.candidates)
  ? payload.candidates
      .map(candidate => candidate?.finishReason ?? candidate?.finish_reason)
      .filter(Boolean)
  : [];

const incompleteReasons = finishReasons.filter(reason => reason !== 'STOP');

if (incompleteReasons.length) {
  throw new Error(
    `TEXT_EXTRACTION_INCOMPLETE: finishReasons=${incompleteReasons.join(',')}`
  );
}



// ==============================
// DEBUG KHI KHÔNG CÓ TEXT
// ==============================
if (!raw) {
  const candidate = payload?.candidates?.[0];

  const finishReason =
    candidate?.finishReason ??
    candidate?.finish_reason ??
    'unknown';

  const parts = candidate?.content?.parts;

  throw new Error(
    `TEXT_EXTRACTION_EMPTY: ` +
    `keys=${Object.keys(payload || {}).join(',')} ` +
    `finishReason=${finishReason} ` +
    `parts=${Array.isArray(parts) ? parts.length : 0}`
  );
}


// ==============================
// NORMALIZE
// ==============================
const normalized = raw
  .replace(/\r\n?/g, '\n')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n{3,}/g, '\n\n')
  .split('\n')
  .map(line => line.trimEnd())
  .join('\n')
  .trim();


// ==============================
// PRODUCT NAMES
// ==============================
const sourceNames = [
  ...new Set(
    normalized.match(
      /\b(?:GstarCAD|CMS IntelliCAD|IntelliCAD|enjiCAD|ENJICAD)\b/gi
    ) || []
  )
];


// ==============================
// ENGINE
// ==============================
const isOffice = [
  'application/vnd.openxmlformats-officedocument.presentationml.presentation',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
].includes(meta.mime_type);

const isGemini = Array.isArray(payload?.candidates);

const engine =
  payload.engine ||
  (
    isGemini
      ? 'gemini'
      : isOffice
        ? 'office-parser'
        : 'PP-StructureV3'
  );


// ==============================
// OUTPUT
// ==============================
return [
  {
    json: {
      ...meta,

      raw_text: raw,
      normalized_text: normalized,

      source_product_names: sourceNames,
      normalized_product_name: 'ENJICAD',

      extraction: {
        engine,
        used_ocr:
          payload.used_ocr ??
          (isGemini ? true : false),
        pages: payload.pages || null,
        batching: payload.ocr_batching || null,

        model:
          payload.modelVersion ??
          response.modelVersion ??
          null,

        response_id:
          payload.responseId ??
          response.responseId ??
          null
      }
    }
  }
];

const ctx = $('Resolve Product And KB1').item.json;
const found = $input.all().map(i=>i.json).find(r=>r?.knowledge_base_id && r?.product_id);
return [{json:{...ctx,binding_exists:Boolean(found),binding_payload:{knowledge_base_id:ctx.knowledge_base_id,product_id:ctx.product_id}}}];

const ctx = $('Ensure Product-KB Binding1').item.json;
if (!ctx?.product_id || !ctx?.knowledge_base_id) throw new Error('INGESTION_CONTEXT_MISSING_PRODUCT_OR_KB');
return [{json:{...ctx}}];

const ctx = $('Prepare New Version2').item.json;
const rows = $input.all().map(i=>i.json);
const row = rows.find(r=>r?.id) || (Array.isArray(rows[0]) ? rows[0][0] : null);
if (!row?.id) throw new Error('DOCUMENT_VERSION_CREATE_FAILED');
return [{json:{...ctx,document_version_id:row.id}}];

const ctx = $json;
const text = String(ctx.normalized_text || '').trim();
const MAX = 4200;
const MIN = 500;
if (!text) throw new Error('SEMANTIC_CHUNKING_INPUT_EMPTY');

const blocks = text
  .split(/\n(?=#{1,6}\s|\d+(?:\.\d+)*[.)]\s|(?:FAQ|Error|Cause|Solution|Lỗi|Nguyên nhân|Giải pháp)\b)/i)
  .map(value => value.trim())
  .filter(Boolean);
const chunks = [];
let buffer = '';
for (const block of blocks) {
  if (buffer && buffer.length + 2 + block.length > MAX) {
    chunks.push(buffer);
    buffer = '';
  }
  if (block.length > MAX) {
    if (buffer) {
      chunks.push(buffer);
      buffer = '';
    }
    for (let start = 0; start < block.length;) {
      let end = Math.min(start + MAX, block.length);
      if (end < block.length) {
        const newline = block.lastIndexOf('\n', end);
        const sentence = block.lastIndexOf('. ', end);
        const cut = Math.max(newline, sentence);
        if (cut > start + MIN) end = cut + 1;
      }
      const content = block.slice(start, end).trim();
      if (content) chunks.push(content);
      start = end;
    }
  } else {
    buffer = buffer ? `${buffer}\n\n${block}` : block;
  }
}
if (buffer) chunks.push(buffer);
if (!chunks.length) throw new Error('SEMANTIC_CHUNKING_EMPTY');
if (chunks.some(chunk => chunk.length > MAX)) throw new Error('SEMANTIC_CHUNKING_MAX_LENGTH_VIOLATION');

function hash(value) {
  let result = 2166136261;
  for (let index = 0; index < value.length; index++) {
    result ^= value.charCodeAt(index);
    result = Math.imul(result, 16777619);
  }
  return (result >>> 0).toString(16).padStart(8, '0');
}

return chunks.map((content, index) => ({
  json: {
    document_version_id: ctx.document_version_id,
    product_id: ctx.product_id,
    chunk_index: index,
    section: (content.split('\n')[0] || 'DOCUMENT').slice(0, 240),
    title: `${ctx.file_name} - Chunk ${index + 1}`,
    content,
    language_code: ctx.language_code,
    content_hash: hash(content),
    metadata: {
      knowledge_base_id: ctx.knowledge_base_id,
      file_id: ctx.file_id,
      source_url: ctx.source_url,
      source_product_names: ctx.source_product_names,
      normalized_product_name: 'ENJICAD',
      chunking: 'semantic-v1'
    }
  }
}));

const SOURCE_DIMENSION=4096;
const STORAGE_DIMENSION=1024;
const responses=$input.all();
const src=$('Prepare Embedding Input2').all();
if(responses.length!==src.length)throw new Error(`EMBEDDING_RESPONSE_COUNT_MISMATCH ${responses.length}/${src.length}`);
return responses.map((item,i)=>{
  const r=item.json||{};
  const e=r?.data?.[0]?.embedding??r.embedding;
  const model=String(r.model||'qwen3-embedding-8b').toLowerCase();
  if(model!=='qwen3-embedding-8b')throw new Error(`WRONG_EMBEDDING_MODEL item=${i} model=${model}`);
  if(!Array.isArray(e)||e.length!==SOURCE_DIMENSION)throw new Error(`WRONG_EMBEDDING_DIMENSION item=${i} expected=${SOURCE_DIMENSION} actual=${Array.isArray(e)?e.length:'invalid'}`);
  const truncated=e.slice(0,STORAGE_DIMENSION).map(Number);
  if(truncated.some(v=>!Number.isFinite(v)))throw new Error(`INVALID_EMBEDDING_VALUE item=${i}`);
  const norm=Math.sqrt(truncated.reduce((s,v)=>s+v*v,0));
  if(!Number.isFinite(norm)||norm<=1e-12)throw new Error(`INVALID_EMBEDDING_NORM item=${i}`);
  const normalized=truncated.map(v=>v/norm);
  return {json:{...src[i].json,embedding:normalized,dimension:STORAGE_DIMENSION,source_dimension:SOURCE_DIMENSION,embedding_model_name:model}};
});

const versionId=$('Resolve Version ID1').item.json.document_version_id;
const rawChunks=$('Supabase - Get Version Chunks1').all().map(i=>i.json).filter(r=>r?.id);
const chunkMap=new Map(rawChunks.map(r=>[String(r.id),r]));
const chunks=[...chunkMap.values()];
const embeddingRows=$input.all().map(i=>i.json).filter(r=>r?.id&&r?.chunk_id);
const embeddedChunkIds=new Set(embeddingRows.map(r=>String(r.chunk_id)));
const totalChunks=chunks.length;
const embedded=chunks.filter(c=>embeddedChunkIds.has(String(c.id))).length;
const failed=totalChunks-embedded;
if(!totalChunks)throw new Error('VALIDATION_NO_CHUNKS');
return [{json:{document_version_id:versionId,total_chunks:totalChunks,total_embeddings:embedded,failed_embeddings:failed,rag_complete:failed===0}}];

const raw = $json.data ?? $json;

// Nếu OpenAPI schema đang là string thì parse thành object
const spec = typeof raw === 'string'
  ? JSON.parse(raw)
  : raw;

const allowed = [
  'product_features',
  'product_attributes',
  'product_file_formats',
  'product_system_requirements',
  'product_applications',
  'product_faqs',
  'product_relations',
  'product_versions',
  'product_fact_sources'
];

const defs =
  spec.definitions ||
  spec.components?.schemas ||
  {};

const contract = {};

for (const table of allowed) {
  const d = defs[table];

  if (!d) {
    throw new Error(`SCHEMA_NOT_EXPOSED: ${table}`);
  }

  contract[table] = {
    required: d.required || [],
    properties: Object.fromEntries(
      Object.entries(d.properties || {}).map(([k, v]) => [
        k,
        {
          type: v.type || v.format || null,
          format: v.format || null,
          default: v.default ?? null,
          description: v.description || ''
        }
      ])
    )
  };
}

return [
  {
    json: {
      schema_contract: contract
    }
  }
];

