={{ JSON.stringify({
  model:'qwen3-vl-30b',
  temperature:0,
  max_tokens:8192,
  response_format:{type:'json_object'},
  messages:[
    {role:'system',content:'Extract only facts explicitly supported by this source batch. Never invent facts. Preserve technical names, paths, services and executables. Normalize product scope to ENJICAD. Return ONLY valid JSON without Markdown: {writes:[{table,payload,dedupe,source_text,confidence}]}. Return at most 6 highest-value writes for this batch. Keep every payload concise and include only columns materially supported by the source. dedupe MUST be a JSON object containing stable natural-key columns, never a string. Never include id, created_at or updated_at in payload or dedupe; the database manages them. Keep source_text at most 240 characters and escape JSON characters correctly. table must be one of product_features, product_attributes, product_file_formats, product_system_requirements, product_applications, product_faqs, product_relations, product_versions. payload and dedupe keys must exist in the schema. Empty batch means {writes:[]}.'},
    {role:'user',content:'BATCH '+($json.batch_index+1)+'/'+$json.batch_count+'\nPRODUCT_ID: '+$json.product_id+'\nSCHEMA:\n'+JSON.stringify($json.schema_contract)+'\nSOURCE:\n'+$json.batch_text}
  ]
}) }}

parameters.jsCode:
const batches=$input.all().map(item=>item.json);
const schema=batches[0]?.schema_contract??$('Prepare Structured Schema Contract1').item.json.schema_contract;
const version=$('Resolve Version ID1').item.json;
const allowed=new Set(Object.keys(schema).filter(table=>table!=='product_fact_sources'));
const rawEntries=batches.flatMap(batch=>(Array.isArray(batch.writes)?batch.writes:[]).map(write=>({write,source_batch_index:batch.batch_index})));
const malformedEntries=rawEntries.filter(entry=>!entry.write||typeof entry.write!=='object'||Array.isArray(entry.write)||typeof entry.write.table!=='string'||!entry.write.payload||typeof entry.write.payload!=='object'||Array.isArray(entry.write.payload));
const structurallyValid=rawEntries.filter(entry=>!malformedEntries.includes(entry)).map(entry=>({...entry.write,source_batch_index:entry.source_batch_index}));
for(const write of structurallyValid){if(write.table==='product_file_formats'){const direction=String(write.payload?.direction||'').toLowerCase();const normalized=direction==='input'?'import':direction==='output'?'export':direction;if(write.payload)write.payload.direction=normalized;if(write.dedupe&&typeof write.dedupe==='object')write.dedupe.direction=normalized;const rawExtension=String(write.payload?.extension||'').trim().toLowerCase();if(rawExtension){const extension=rawExtension.startsWith('.')?rawExtension:'.'+rawExtension;write.payload.extension=extension;if(write.dedupe&&typeof write.dedupe==='object')write.dedupe.extension=extension;}}}
const semanticInvalidEntries=structurallyValid.filter(write=>write.table==='product_file_formats'&&!['import','export','both'].includes(String(write.payload?.direction||'').toLowerCase()));
const invalidEntries=[...malformedEntries,...semanticInvalidEntries];
const rawWrites=structurallyValid.filter(write=>!semanticInvalidEntries.includes(write));
const unique=new Map();
for(let i=0;i<rawWrites.length;i++){
  const write=rawWrites[i];
  if(!allowed.has(write.table))throw new Error('STRUCTURED_TABLE_NOT_ALLOWED item='+i+' table='+write.table);
  const def=schema[write.table];const props=def.properties||{};
  const payload={};
  const managed=new Set(['id','created_at','updated_at']);
  for(const [key,value] of Object.entries(write.payload||{}))if(key in props&&!managed.has(key))payload[key]=value;
  let dedupe=write.dedupe&&typeof write.dedupe==='object'&&!Array.isArray(write.dedupe)?{...write.dedupe}:{};
  dedupe=Object.fromEntries(Object.entries(dedupe).filter(([key,value])=>key in props&&!managed.has(key)&&value!==null&&value!==undefined&&String(value)!==''));
  if('product_id'in props){payload.product_id=version.product_id;dedupe.product_id=version.product_id;}
  if(Object.keys(dedupe).filter(key=>key!=='product_id').length===0){
    const strong=['feature_key','attribute_key','format_key','requirement_key','application_key','faq_key','relation_key','version_key','code','slug','version','extension','mime_type','relation_type','source_product_id','target_product_id'];
    for(const key of strong){const value=payload[key];if(key in props&&value!==null&&value!==undefined&&String(value)!=='')dedupe[key]=value;}
    if(Object.keys(dedupe).filter(key=>key!=='product_id').length&&'language_code'in props&&payload.language_code)dedupe.language_code=payload.language_code;
  }
  if(Object.keys(dedupe).filter(key=>key!=='product_id').length===0){
    const names=['question','name','title','feature_name','attribute_name','format_name','requirement_name','application_name'];
    const key=names.find(candidate=>candidate in props&&payload[candidate]!==null&&payload[candidate]!==undefined&&String(payload[candidate])!=='');
    if(key)dedupe[key]=payload[key];
    if(key&&'language_code'in props&&payload.language_code)dedupe.language_code=payload.language_code;
  }
  if(Object.keys(dedupe).filter(key=>key!=='product_id').length===0){
    const fallback=Object.keys(payload).find(key=>key!=='product_id'&&!managed.has(key)&&['string','number','boolean'].includes(typeof payload[key])&&String(payload[key]).length<=240);
    if(fallback)dedupe[fallback]=payload[fallback];
  }
  const identityKeysByTable={
    product_features:['feature_key','language_code'],
    product_attributes:['attribute_key','language_code'],
    product_file_formats:['direction','extension','language_code'],
    product_system_requirements:['requirement_key','language_code'],
    product_applications:['application','language_code'],
    product_faqs:['faq_key','language_code'],
    product_relations:['source_product_id','target_product_id','relation_type'],
    product_versions:['version_key','language_code']
  };
  const identityKeys=identityKeysByTable[write.table]||[];
  if(identityKeys.length){
    const canonical={};
    if('product_id'in props)canonical.product_id=version.product_id;
    for(const key of identityKeys){
      const value=payload[key];
      if(key in props&&value!==null&&value!==undefined&&String(value)!=='')canonical[key]=value;
    }
    if(Object.keys(canonical).some(key=>key!=='product_id'))dedupe=canonical;
  }
  for(const key of def.required||[]){const property=props[key]||{};if(!(key in payload)&&property.default==null&&!['id','created_at','updated_at'].includes(key))throw new Error('MISSING_REQUIRED_COLUMN '+write.table+'.'+key);}
  const entries=Object.entries(dedupe).filter(([,value])=>value!==null&&value!==undefined&&String(value)!=='');
  if(!entries.length)throw new Error('MISSING_DEDUPE '+write.table);
  const stable=entries.sort(([a],[b])=>a.localeCompare(b));
  const caseInsensitiveIdentityKeys=new Set(['feature_key','attribute_key','format_key','requirement_key','application_key','faq_key','relation_key','version_key','code','slug','extension','mime_type','relation_type','application']);
  const identityStable=stable.map(([key,value])=>[key,caseInsensitiveIdentityKeys.has(key)&&typeof value==='string'?value.toLowerCase():value]);
  const identity=write.table+'|'+JSON.stringify(identityStable);
  const confidenceNumber=Number(write.confidence);const confidence=Number.isFinite(confidenceNumber)?Math.min(1,Math.max(0,confidenceNumber)):0;
  const normalized={table:write.table,payload,dedupe:Object.fromEntries(stable),source_text:String(write.source_text||'').slice(0,240),confidence,source_batch_indexes:[write.source_batch_index]};
  if(unique.has(identity)){
    const current=unique.get(identity);current.confidence=Math.max(current.confidence,confidence);current.source_batch_indexes=[...new Set([...current.source_batch_indexes,write.source_batch_index])];
    if(normalized.source_text.length>current.source_text.length)current.source_text=normalized.source_text;
  }else unique.set(identity,normalized);
}
const writes=[...unique.values()];
if(!writes.length)return [{json:{document_version_id:version.document_version_id,product_id:version.product_id,schema_contract:schema,noop:true,write_index:0,structured_write_count:0,structured_batch_count:batches.length,structured_invalid_write_count:invalidEntries.length}}];
return writes.map((write,write_index)=>{
  const caseInsensitiveKeys=new Set(['feature_key','attribute_key','format_key','requirement_key','application_key','faq_key','relation_key','version_key','code','slug','extension','mime_type','relation_type']);const filters=Object.entries(write.dedupe).map(([key,value])=>{const operator=caseInsensitiveKeys.has(key)&&typeof value==='string'?'ilike':'eq';return encodeURIComponent(key)+'='+operator+'.'+encodeURIComponent(String(value));}).join('&');
  return {json:{...write,document_version_id:version.document_version_id,product_id:version.product_id,source_product_names:version.source_product_names||[],schema_contract:schema,noop:false,write_index,structured_write_count:writes.length,structured_batch_count:batches.length,structured_invalid_write_count:invalidEntries.length,lookup_url:$env.SUPABASE_URL.replace(/\/$/,'')+'/rest/v1/'+write.table+'?select=*&'+filters+'&limit=1'}};
});

const ctx=$('Normalize Existing Structured Fact1').item.json;
const raw=$json?.data??$json;
const created=Array.isArray(raw)?raw[0]:raw;
const row=ctx.fact_exists?ctx.existing_fact:created;
if(!row?.id)throw new Error('STRUCTURED_FACT_ID_MISSING table='+ctx.table+' write_index='+ctx.write_index);
return {json:{...ctx,fact_id:row.id,fact_created:!ctx.fact_exists}};

const ctx=$json;
const def=ctx.schema_contract.product_fact_sources;const props=def.properties||{};
let fk=null;for(const [name,property] of Object.entries(props)){if(String(property.description||'').includes("table='"+ctx.table+"'")){fk=name;break;}}
if(!fk)return {json:{...ctx,skip_provenance:true}};
const payload={[fk]:ctx.fact_id};
if('document_version_id'in props)payload.document_version_id=ctx.document_version_id;
const chunks=$('Create Product Chunks1').all().map(item=>item.json?.data??item.json).flatMap(row=>Array.isArray(row)?row:[row]).filter(row=>row?.id);
const needle=ctx.source_text.slice(0,120).trim();const chunk=needle?chunks.find(row=>String(row.content||'').includes(needle)):null;
if(chunk&&'chunk_id'in props)payload.chunk_id=chunk.id;
if(chunk?.page_number!=null&&'page_number'in props)payload.page_number=chunk.page_number;
if('source_excerpt'in props)payload.source_excerpt=ctx.source_text;else if('source_text'in props)payload.source_text=ctx.source_text;else if('evidence_text'in props)payload.evidence_text=ctx.source_text;
if('confidence'in props)payload.confidence=ctx.confidence;else if('confidence_score'in props)payload.confidence_score=ctx.confidence;
if('extraction_method'in props)payload.extraction_method='qwen3-vl-30b-batched';
if('metadata'in props)payload.metadata={source_product_names:ctx.source_product_names,normalized_product_name:'ENJICAD',source_batch_indexes:ctx.source_batch_indexes};
for(const key of def.required||[]){const property=props[key]||{};if(!(key in payload)&&property.default==null&&!['id','created_at','updated_at'].includes(key))throw new Error('PROVENANCE_MISSING_REQUIRED '+key);}
const keys=[fk,'document_version_id','chunk_id'].filter(key=>key in payload);
const filters=keys.map(key=>encodeURIComponent(key)+'=eq.'+encodeURIComponent(String(payload[key]))).join('&');
return {json:{...ctx,skip_provenance:false,provenance_payload:payload,provenance_lookup_url:$env.SUPABASE_URL.replace(/\/$/,'')+'/rest/v1/product_fact_sources?select=*&'+filters+'&limit=1'}};

const validation=$('Validate RAG Ingestion1').first().json;
if(!validation.rag_complete)throw new Error('FINALIZE_BLOCKED_RAG_INCOMPLETE');
const writes=$('Validate Structured Writes1').all().map(item=>item.json);
const structured=writes.filter(write=>!write.noop);
return [{json:{...validation,status:'completed',structured_batch_count:writes[0]?.structured_batch_count??0,structured_write_count:structured.length,structured_fact_count:structured.length,structured_noop:structured.length===0,completed_at:new Date().toISOString()}}];

const v=$('Finalize Version1').first().json;
const ctx=$('Attach Extracted Context1').first().json;
return [{json:{status:'completed',file_id:ctx.file_id,file_name:ctx.file_name,document_version_id:v.document_version_id,total_chunks:v.total_chunks,total_embeddings:v.total_embeddings,failed_embeddings:v.failed_embeddings,structured_fact_count:v.structured_fact_count,embedding_dimension:1024,source_type:ctx.mime_type === 'application/vnd.google-apps.spreadsheet' ? 'google_sheets' : 'google_drive'}}];

