function firstObject(value){
  const text=String(value??'').replace(/^\uFEFF/,'').replace(/<think>[\s\S]*?<\/think>/gi,'').trim();
  let start=-1,depth=0,inString=false,escaped=false;
  for(let i=0;i<text.length;i++){
    const ch=text[i];
    if(start<0){if(ch==='{'){start=i;depth=1;}continue;}
    if(inString){if(escaped){escaped=false;continue;}if(ch==='\\'){escaped=true;continue;}if(ch==='"')inString=false;continue;}
    if(ch==='"'){inString=true;continue;}if(ch==='{')depth++;else if(ch==='}'&&--depth===0)return {text:text.slice(start,i+1),balanced:true};
  }
  return {text:start>=0?text.slice(start):text,balanced:false};
}
function sanitize(value){
  let out='',inString=false,escaped=false;
  for(let i=0;i<value.length;i++){
    const ch=value[i];
    if(inString){
      if(escaped){out+=ch;escaped=false;continue;}
      if(ch==='\\'){out+=ch;escaped=true;continue;}
      if(ch==='"'){out+=ch;inString=false;continue;}
      const code=ch.charCodeAt(0);
      if(code<32){out+=ch==='\n'?'\\n':ch==='\r'?'\\r':ch==='\t'?'\\t':'\\u'+code.toString(16).padStart(4,'0');continue;}
      out+=ch;continue;
    }
    if(ch==='"'){inString=true;out+=ch;continue;}
    if(ch===','){
      let j=i+1;while(j<value.length&&/\s/.test(value[j]))j++;
      if(value[j]==='}'||value[j]===']')continue;
    }
    out+=ch;
  }
  return out;
}
