const JSZip = require('jszip');

const items = $input.all();
if (items.length !== 1) throw new Error(`OFFICE_BATCH_EXPECTED_ONE_FILE received=${items.length}`);

const source = items[0];
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const meta = $('Prepare Source Metadata1').item.json;
const mimeType = source.binary?.data?.mimeType || meta.mime_type;
const fileName = source.binary?.data?.fileName || meta.file_name || 'office-document';
const DOCX = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
const PPTX = 'application/vnd.openxmlformats-officedocument.presentationml.presentation';
if (![DOCX, PPTX].includes(mimeType)) throw new Error(`OFFICE_BATCH_INVALID_MIME ${mimeType}`);

const sizeBytes = buffer.length;
const sizeMb = sizeBytes / (1024 * 1024);
const xmlText = async (zip, name, required = true) => {
  const entry = zip.file(name);
  if (!entry) {
    if (required) throw new Error(`OOXML_REQUIRED_PART_MISSING ${name}`);
    return null;
  }
  return entry.async('string');
};

function normalizePart(path) {
  const out = [];
  for (const segment of String(path).replace(/\\/g, '/').split('/')) {
    if (!segment || segment === '.') continue;
    if (segment === '..') out.pop();
    else out.push(segment);
  }
  return out.join('/');
}

function resolveTarget(sourcePart, target) {
  if (String(target).startsWith('/')) return normalizePart(String(target).slice(1));
  const slash = sourcePart.lastIndexOf('/');
  const dir = slash >= 0 ? sourcePart.slice(0, slash + 1) : '';
  return normalizePart(dir + target);
}

function relsPathForPart(part) {
  if (!part) return '_rels/.rels';
  const slash = part.lastIndexOf('/');
  const dir = slash >= 0 ? part.slice(0, slash + 1) : '';
  const base = slash >= 0 ? part.slice(slash + 1) : part;
  return `${dir}_rels/${base}.rels`;
}

function attr(tag, name) {
  const match = tag.match(new RegExp(`\\b${name}="([^"]*)"`));
  return match ? match[1] : null;
}

function relationshipTags(xml) {
  return String(xml || '').match(/<Relationship\b[^>]*\/?\s*>/g) || [];
}

function replaceRelationshipTags(xml, tags) {
  const open = xml.match(/<Relationships\b[^>]*>/);
  if (!open) throw new Error('OOXML_RELATIONSHIPS_ROOT_INVALID');
  const closeAt = xml.lastIndexOf('</Relationships>');
  if (closeAt < 0) throw new Error('OOXML_RELATIONSHIPS_CLOSE_MISSING');
  return xml.slice(0, open.index + open[0].length) + tags.join('') + xml.slice(closeAt);
}

async function pruneToReachable(zip) {
  const keep = new Set(['[Content_Types].xml', '_rels/.rels']);
  const queue = [''];
  const seen = new Set();
  while (queue.length) {
    const part = queue.shift();
    if (seen.has(part)) continue;
    seen.add(part);
    if (part) keep.add(part);
    const relsPath = relsPathForPart(part);
    const relsEntry = zip.file(relsPath);
    if (!relsEntry) continue;
    keep.add(relsPath);
    const relsXml = await relsEntry.async('string');
    for (const tag of relationshipTags(relsXml)) {
      if (String(attr(tag, 'TargetMode') || '').toLowerCase() === 'external') continue;
      const target = attr(tag, 'Target');
      if (!target) continue;
      const resolved = resolveTarget(part, target);
      if (zip.file(resolved) && !seen.has(resolved)) queue.push(resolved);
    }
  }

  const contentTypes = await xmlText(zip, '[Content_Types].xml');
  const cleanedContentTypes = contentTypes.replace(/<Override\b[^>]*\/?\s*>/g, tag => {
    const partName = attr(tag, 'PartName');
    if (!partName) return tag;
    return keep.has(normalizePart(partName.replace(/^\//, ''))) ? tag : '';
  });
  zip.file('[Content_Types].xml', cleanedContentTypes);

  for (const name of Object.keys(zip.files)) {
    if (zip.files[name].dir) continue;
    if (!keep.has(name)) zip.remove(name);
  }
}

async function generatePrunedPackage(changes) {
  const zip = await JSZip.loadAsync(buffer);
  const rootRelsPath = '_rels/.rels';
  const rootRelsXml = await xmlText(zip, rootRelsPath);
  const rootRelsWithoutThumbnail = replaceRelationshipTags(
    rootRelsXml,
    relationshipTags(rootRelsXml).filter(tag => !String(attr(tag, 'Type') || '').endsWith('/thumbnail'))
  );
  zip.file(rootRelsPath, rootRelsWithoutThumbnail);
  for (const [name, value] of Object.entries(changes)) zip.file(name, value);
  await pruneToReachable(zip);
  return Buffer.from(await zip.generateAsync({
    type: 'nodebuffer',
    compression: 'DEFLATE',
    compressionOptions: { level: 6 },
    platform: 'UNIX'
  }));
}

function splitTopLevelBodyChildren(innerXml) {
  const blocks = [];
  const tagRe = /<!--[\s\S]*?-->|<\?[\s\S]*?\?>|<!\[CDATA\[[\s\S]*?\]\]>|<[^>]+>/g;
  let depth = 0;
  let start = null;
  let match;
  while ((match = tagRe.exec(innerXml))) {
    const tag = match[0];
    if (tag.startsWith('<!--') || tag.startsWith('<?') || tag.startsWith('<![CDATA[')) continue;
    const closing = /^<\//.test(tag);
    const selfClosing = /\/\s*>$/.test(tag);
    if (!closing) {
      if (depth === 0) start = match.index;
      if (selfClosing) {
        if (depth === 0 && start !== null) {
          blocks.push(innerXml.slice(start, tagRe.lastIndex));
          start = null;
        }
      } else {
        depth += 1;
      }
    } else {
      depth -= 1;
      if (depth < 0) throw new Error('DOCX_BODY_XML_DEPTH_INVALID');
      if (depth === 0 && start !== null) {
        blocks.push(innerXml.slice(start, tagRe.lastIndex));
        start = null;
      }
    }
  }
  if (depth !== 0) throw new Error(`DOCX_BODY_XML_UNBALANCED depth=${depth}`);
  return blocks.filter(block => block.trim());
}

function referencedRelationshipIds(xml) {
  const ids = new Set();
  const re = /\br:(?:id|embed|link)="([^"]+)"/g;
  let match;
  while ((match = re.exec(xml))) ids.add(match[1]);
  return ids;
}

function compressedEntrySize(zip, name) {
  const entry = zip.file(name);
  return Number(entry?._data?.compressedSize || entry?._data?.uncompressedSize || 0);
}

function greedyRanges(weights, targetBytes) {
  const ranges = [];
  let start = 0;
  let current = 0;
  for (let i = 0; i < weights.length; i++) {
    const weight = Math.max(1, Number(weights[i]) || 0);
    if (i > start && current + weight > targetBytes) {
      ranges.push([start, i]);
      start = i;
      current = 0;
    }
    current += weight;
  }
  if (start < weights.length) ranges.push([start, weights.length]);
  return ranges;
}

async function buildDocxBatches() {
  const sourceZip = await JSZip.loadAsync(buffer);
  const documentPath = 'word/document.xml';
  const relsPath = 'word/_rels/document.xml.rels';
  const documentXml = await xmlText(sourceZip, documentPath);
  const relsXml = await xmlText(sourceZip, relsPath);
  const bodyOpen = documentXml.match(/<w:body\b[^>]*>/);
  const bodyCloseAt = documentXml.lastIndexOf('</w:body>');
  if (!bodyOpen || bodyCloseAt < 0) throw new Error('DOCX_BODY_NOT_FOUND');
  const bodyStart = bodyOpen.index + bodyOpen[0].length;
  const prefix = documentXml.slice(0, bodyStart);
  const suffix = documentXml.slice(bodyCloseAt);
  const allBlocks = splitTopLevelBodyChildren(documentXml.slice(bodyStart, bodyCloseAt));
  if (!allBlocks.length) throw new Error('DOCX_BODY_EMPTY');

  let finalSectPr = '';
  if (/^<w:sectPr\b/.test(allBlocks[allBlocks.length - 1].trim())) finalSectPr = allBlocks.pop();
  if (!allBlocks.length) throw new Error('DOCX_CONTENT_BLOCKS_EMPTY');

  const relTags = relationshipTags(relsXml);
  const relById = new Map(relTags.map(tag => [attr(tag, 'Id'), tag]));
  const weights = allBlocks.map(block => {
    let weight = Buffer.byteLength(block, 'utf8');
    const targets = new Set();
    for (const id of referencedRelationshipIds(block)) {
      const tag = relById.get(id);
      const target = tag && attr(tag, 'Target');
      if (target && String(attr(tag, 'TargetMode') || '').toLowerCase() !== 'external') {
        targets.add(resolveTarget(documentPath, target));
      }
    }
    for (const target of targets) weight += compressedEntrySize(sourceZip, target);
    return weight;
  });

  let targetMb;
  let strategy;
  if (sizeMb <= 10) {
    targetMb = Infinity;
    strategy = 'docx_whole_file_le_10mb';
  } else if (sizeMb <= 20) {
    targetMb = 8;
    strategy = 'docx_10_to_20mb_logical_batches';
  } else if (sizeMb <= 50) {
    targetMb = 6;
    strategy = 'docx_20_to_50mb_logical_batches';
  } else {
    targetMb = 4.5;
    strategy = 'docx_over_50mb_logical_batches';
  }
  const initialRanges = Number.isFinite(targetMb)
    ? greedyRanges(weights, targetMb * 1024 * 1024)
    : [[0, allBlocks.length]];

  async function renderRange(start, end) {
    const selectedBlocks = allBlocks.slice(start, end);
    const bodyXml = selectedBlocks.join('') + finalSectPr;
    const selectedIds = referencedRelationshipIds(bodyXml);
    const keptRels = relTags.filter(tag => {
      const id = attr(tag, 'Id');
      const type = attr(tag, 'Type') || '';
      const target = attr(tag, 'Target') || '';
      if (selectedIds.has(id)) return true;
      if (String(attr(tag, 'TargetMode') || '').toLowerCase() === 'external') return false;
      const removablePayload = /\/(?:image|chart|diagramData|diagramLayout|diagramColors|diagramQuickStyle|oleObject|package|header|footer)$/.test(type)
        || /(?:^|\/)(?:media|embeddings|charts|diagrams|header\d+\.xml|footer\d+\.xml)(?:\/|$)/i.test(target);
      return !removablePayload;
    });
    const bytes = await generatePrunedPackage({
      [documentPath]: prefix + bodyXml + suffix,
      [relsPath]: replaceRelationshipTags(relsXml, keptRels)
    });
    return { start, end, bytes };
  }

  const rendered = [];
  async function renderSafely(start, end) {
    const batch = await renderRange(start, end);
    const maxBytes = 9 * 1024 * 1024;
    if (sizeMb > 10 && batch.bytes.length > maxBytes && end - start > 1) {
      const mid = start + Math.floor((end - start) / 2);
      await renderSafely(start, mid);
      await renderSafely(mid, end);
    } else {
      rendered.push(batch);
    }
  }
  for (const [start, end] of initialRanges) await renderSafely(start, end);
  return rendered.map(batch => ({
    ...batch,
    pageStart: null,
    pageEnd: null,
    pageCount: null,
    unitsInBatch: batch.end - batch.start,
    unitName: 'document_blocks',
    strategy
  }));
}

async function buildPptxBatches() {
  const sourceZip = await JSZip.loadAsync(buffer);
  const presentationPath = 'ppt/presentation.xml';
  const relsPath = 'ppt/_rels/presentation.xml.rels';
  const presentationXml = await xmlText(sourceZip, presentationPath);
  const relsXml = await xmlText(sourceZip, relsPath);
  const listMatch = presentationXml.match(/<p:sldIdLst\b[^>]*>([\s\S]*?)<\/p:sldIdLst>/);
  if (!listMatch) throw new Error('PPTX_SLIDE_LIST_NOT_FOUND');
  const slideTags = listMatch[1].match(/<p:sldId\b[^>]*\/?\s*>/g) || [];
  if (!slideTags.length) throw new Error('PPTX_SLIDE_LIST_EMPTY');
  const slideRids = slideTags.map(tag => attr(tag, 'r:id'));
  if (slideRids.some(id => !id)) throw new Error('PPTX_SLIDE_RELATIONSHIP_ID_MISSING');
  const relTags = relationshipTags(relsXml);

  let slidesPerBatch;
  let strategy;
  if (sizeMb <= 10 && slideTags.length <= 50) {
    slidesPerBatch = slideTags.length;
    strategy = 'pptx_whole_file_le_10mb_le_50_slides';
  } else if (sizeMb <= 20) {
    slidesPerBatch = 20;
    strategy = sizeMb <= 10 ? 'pptx_over_50_slides_20_per_batch' : 'pptx_10_to_20mb_20_slides_per_batch';
  } else if (sizeMb <= 50) {
    slidesPerBatch = 10;
    strategy = 'pptx_20_to_50mb_10_slides_per_batch';
  } else {
    slidesPerBatch = 5;
    strategy = 'pptx_over_50mb_5_slides_per_batch';
  }

  async function renderRange(start, end) {
    const keepRids = new Set(slideRids.slice(start, end));
    const keptSlideTags = slideTags.slice(start, end);
    const newPresentation = presentationXml.replace(listMatch[0], listMatch[0].replace(listMatch[1], keptSlideTags.join('')));
    const newRels = replaceRelationshipTags(relsXml, relTags.filter(tag => {
      const type = attr(tag, 'Type') || '';
      return !type.endsWith('/slide') || keepRids.has(attr(tag, 'Id'));
    }));
    const bytes = await generatePrunedPackage({
      [presentationPath]: newPresentation,
      [relsPath]: newRels
    });
    return { start, end, bytes };
  }

  const rendered = [];
  async function renderSafely(start, end) {
    const batch = await renderRange(start, end);
    const maxBytes = 9 * 1024 * 1024;
    if (sizeMb > 10 && batch.bytes.length > maxBytes && end - start > 1) {
      const mid = start + Math.floor((end - start) / 2);
      await renderSafely(start, mid);
      await renderSafely(mid, end);
    } else {
      rendered.push(batch);
    }
  }
  for (let start = 0; start < slideTags.length; start += slidesPerBatch) {
    await renderSafely(start, Math.min(start + slidesPerBatch, slideTags.length));
  }
  return rendered.map(batch => ({
    ...batch,
    pageStart: batch.start + 1,
    pageEnd: batch.end,
    pageCount: slideTags.length,
    unitsInBatch: batch.end - batch.start,
    unitName: 'slides',
    strategy
  }));
}

let batches;
try {
  batches = mimeType === DOCX ? await buildDocxBatches() : await buildPptxBatches();
} catch (error) {
  throw new Error(`OFFICE_BATCH_BUILD_FAILED file=${fileName} size_mb=${sizeMb.toFixed(3)} reason=${error.message}`);
}
if (!batches.length) throw new Error('OFFICE_BATCH_BUILD_EMPTY');

const outputs = [];
for (let index = 0; index < batches.length; index++) {
  const batch = batches[index];
  const extension = mimeType === DOCX ? 'docx' : 'pptx';
  const batchName = `${String(fileName).replace(/\.[^.]+$/, '')}.ocr-batch-${String(index + 1).padStart(3, '0')}.${extension}`;
  const binaryData = await this.helpers.prepareBinaryData(batch.bytes, batchName, mimeType);
  outputs.push({
    json: {
      batch_index: index,
      batch_count: batches.length,
      page_start: batch.pageStart,
      page_end: batch.pageEnd,
      page_count: batch.pageCount,
      pages_in_batch: batch.pageCount ? batch.unitsInBatch : null,
      logical_start: batch.start + 1,
      logical_end: batch.end,
      logical_units_in_batch: batch.unitsInBatch,
      logical_unit_name: batch.unitName,
      source_size_bytes: sizeBytes,
      source_size_mb: Number(sizeMb.toFixed(3)),
      batch_size_bytes: batch.bytes.length,
      ocr_batch_strategy: batch.strategy,
      pdf_mime: mimeType,
      pdf_file_name: batchName
    },
    binary: { data: binaryData },
    pairedItem: { item: 0 }
  });
}
return outputs;

