parameters.jsCode:
const { PDFDocument } = require('pdf-lib');
const items = $input.all();
if (items.length !== 1) throw new Error(`PDF_BATCH_EXPECTED_ONE_FILE received=${items.length}`);

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const mimeType = items[0].binary?.data?.mimeType || $('Prepare Source Metadata1').item.json.mime_type;
const fileName = items[0].binary?.data?.fileName || $('Prepare Source Metadata1').item.json.file_name || 'document.pdf';
if (mimeType !== 'application/pdf') throw new Error(`PDF_BATCH_INVALID_MIME ${mimeType}`);

const sizeBytes = buffer.length;
const sizeMb = sizeBytes / (1024 * 1024);
let sourcePdf;
try {
  sourcePdf = await PDFDocument.load(buffer, { updateMetadata: false });
} catch (error) {
  throw new Error(`PDF_BATCH_LOAD_FAILED file=${fileName} reason=${error.message}`);
}
const pageCount = sourcePdf.getPageCount();
if (!Number.isInteger(pageCount) || pageCount < 1) throw new Error('PDF_BATCH_PAGE_COUNT_INVALID');

const wholeFile = sizeMb <= 10 && pageCount <= 50;
let pagesPerBatch;
let strategy;
if (wholeFile) {
  pagesPerBatch = pageCount;
  strategy = 'whole_file_le_10mb_le_50_pages';
} else if (sizeMb <= 20) {
  pagesPerBatch = 20;
  strategy = sizeMb <= 10 ? 'over_50_pages_20_pages_per_batch' : '10_to_20mb_20_pages_per_batch';
} else if (sizeMb <= 50) {
  pagesPerBatch = 10;
  strategy = '20_to_50mb_10_pages_per_batch';
} else {
  pagesPerBatch = 5;
  strategy = 'over_50mb_5_pages_per_batch';
}

const plans = [];
for (let start = 0; start < pageCount; start += pagesPerBatch) {
  plans.push({ start, end: Math.min(start + pagesPerBatch, pageCount) });
}

const outputs = [];
for (let batchIndex = 0; batchIndex < plans.length; batchIndex++) {
  const plan = plans[batchIndex];
  let batchBytes;
  if (wholeFile) {
    batchBytes = buffer;
  } else {
    const batchPdf = await PDFDocument.create();
    const pageIndices = sourcePdf.getPageIndices().slice(plan.start, plan.end);
    const copiedPages = await batchPdf.copyPages(sourcePdf, pageIndices);
    for (const page of copiedPages) batchPdf.addPage(page);
    batchBytes = Buffer.from(await batchPdf.save({ useObjectStreams: true, objectsPerTick: 50 }));
  }
  outputs.push({
    json: {
      batch_index: batchIndex,
      batch_count: plans.length,
      page_start: plan.start + 1,
      page_end: plan.end,
      page_count: pageCount,
      pages_in_batch: plan.end - plan.start,
      source_size_bytes: sizeBytes,
      source_size_mb: Number(sizeMb.toFixed(3)),
      batch_size_bytes: batchBytes.length,
      ocr_batch_strategy: strategy,
      pdf_mime: 'application/pdf',
      pdf_file_name: fileName,
      pdf_base64: batchBytes.toString('base64')
    },
    pairedItem: { item: 0 }
  });
}
return outputs;

const response = $json || {};
const batch = $('Encode Current OCR Batch').item.json;
const payload = response.data && typeof response.data === 'object' && !Array.isArray(response.data)
  ? response.data
  : response;

const apiError = payload?.details?.description
  ?? response?.details?.description
  ?? payload?.error?.description
  ?? response?.error?.description
  ?? payload?.error?.message
  ?? payload?.error?.status
  ?? payload?.details?.message
  ?? response?.error?.message
  ?? response?.details?.message
  ?? (typeof payload?.error === 'string' ? payload.error : null);
if (apiError) {
  const httpCode = payload?.details?.httpCode ?? response?.details?.httpCode ?? payload?.statusCode ?? response?.statusCode ?? 'unknown';
  throw new Error(
    `OCR_BATCH_API_ERROR batch=${batch.batch_index + 1}/${batch.batch_count} ` +
    `pages=${batch.page_start ?? 'n/a'}-${batch.page_end ?? 'n/a'} ` +
    `http=${httpCode} ` +
    `message=${String(apiError).slice(0, 500)}`
  );
}

const candidates = Array.isArray(payload.candidates) ? payload.candidates : [];
const finishReasons = candidates.map(candidate => candidate?.finishReason ?? candidate?.finish_reason).filter(Boolean);
const incomplete = finishReasons.filter(reason => reason !== 'STOP');
if (incomplete.length) throw new Error(`OCR_BATCH_INCOMPLETE batch=${batch.batch_index + 1}/${batch.batch_count} pages=${batch.page_start ?? 'n/a'}-${batch.page_end ?? 'n/a'} reasons=${incomplete.join(',')}`);

const texts = [];
for (const candidate of candidates) {
  const parts = candidate?.content?.parts;
  if (!Array.isArray(parts)) continue;
  for (const part of parts) {
    if (part?.thought === true) continue;
    if (typeof part?.text === 'string' && part.text.trim()) texts.push(part.text.trim());
  }
}
const text = texts.join('\n').trim();
if (!text) throw new Error(`OCR_BATCH_EMPTY batch=${batch.batch_index + 1}/${batch.batch_count} pages=${batch.page_start ?? 'n/a'}-${batch.page_end ?? 'n/a'} response_keys=${Object.keys(payload).join(',')}`);

return [{json:{
  batch_index: batch.batch_index,
  batch_count: batch.batch_count,
  page_start: batch.page_start,
  page_end: batch.page_end,
  page_count: batch.page_count,
  pages_in_batch: batch.pages_in_batch,
  logical_start: batch.logical_start ?? null,
  logical_end: batch.logical_end ?? null,
  logical_units_in_batch: batch.logical_units_in_batch ?? null,
  logical_unit_name: batch.logical_unit_name ?? null,
  source_size_bytes: batch.source_size_bytes,
  source_size_mb: batch.source_size_mb,
  batch_size_bytes: batch.batch_size_bytes,
  ocr_batch_strategy: batch.ocr_batch_strategy,
  text,
  modelVersion: payload.modelVersion ?? response.modelVersion ?? null,
  responseId: payload.responseId ?? response.responseId ?? null
}}];

const batches = $input.all().map(item => item.json).sort((a, b) => Number(a.batch_index) - Number(b.batch_index));
if (!batches.length) throw new Error('OCR_BATCH_MERGE_EMPTY');
const expectedCount = Number(batches[0].batch_count);
if (batches.length !== expectedCount) throw new Error(`OCR_BATCH_MISSING expected=${expectedCount} actual=${batches.length}`);
const isPaginated = Number.isInteger(Number(batches[0].page_count)) && Number(batches[0].page_count) > 0;

for (let index = 0; index < batches.length; index++) {
  const batch = batches[index];
  if (Number(batch.batch_index) !== index) throw new Error(`OCR_BATCH_ORDER_INVALID expected=${index} actual=${batch.batch_index}`);
  if (isPaginated && index === 0 && Number(batch.page_start) !== 1) throw new Error(`OCR_FIRST_PAGE_INVALID ${batch.page_start}`);
  if (isPaginated && index > 0 && Number(batch.page_start) !== Number(batches[index - 1].page_end) + 1) {
    throw new Error(`OCR_PAGE_GAP previous_end=${batches[index - 1].page_end} next_start=${batch.page_start}`);
  }
}
const last = batches[batches.length - 1];
if (isPaginated && Number(last.page_end) !== Number(last.page_count)) throw new Error(`OCR_LAST_PAGE_INVALID end=${last.page_end} total=${last.page_count}`);

const text = batches.map(batch => `${isPaginated ? `<!-- ORIGINAL_PAGES ${batch.page_start}-${batch.page_end} -->\n` : ''}${String(batch.text).trim()}`).join('\n\n').trim();
return [{json:{
  text,
  engine: 'gemini-page-batched-ocr',
  used_ocr: true,
  pages: isPaginated ? Number(last.page_count) : null,
  modelVersion: batches.find(batch => batch.modelVersion)?.modelVersion ?? null,
  responseIds: batches.map(batch => batch.responseId).filter(Boolean),
  ocr_batching: {
    strategy: batches[0].ocr_batch_strategy,
    source_size_bytes: Number(batches[0].source_size_bytes),
    source_size_mb: Number(batches[0].source_size_mb),
    page_count: isPaginated ? Number(last.page_count) : null,
    batch_count: batches.length,
    batches: batches.map(batch => ({
      batch_index: Number(batch.batch_index),
      page_start: isPaginated ? Number(batch.page_start) : null,
      page_end: isPaginated ? Number(batch.page_end) : null,
      pages: isPaginated ? Number(batch.pages_in_batch) : null,
      batch_size_bytes: Number(batch.batch_size_bytes),
      logical_start: batch.logical_start == null ? null : Number(batch.logical_start),
      logical_end: batch.logical_end == null ? null : Number(batch.logical_end),
      logical_units: batch.logical_units_in_batch == null ? null : Number(batch.logical_units_in_batch),
      logical_unit_name: batch.logical_unit_name ?? null
    }))
  }
}}];

const item = $input.first();
if (!item) throw new Error('OCR_BATCH_ENCODE_INPUT_EMPTY');
if (typeof item.json?.pdf_base64 === 'string' && item.json.pdf_base64.length) return [item];
if (!item.binary?.data) throw new Error(`OCR_BATCH_BINARY_MISSING batch=${Number(item.json?.batch_index) + 1}`);
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
if (!buffer.length) throw new Error(`OCR_BATCH_BINARY_EMPTY batch=${Number(item.json?.batch_index) + 1}`);
return [{
  json: {
    ...item.json,
    batch_size_bytes: buffer.length,
    pdf_base64: buffer.toString('base64')
  },
  pairedItem: { item: 0 }
}];

const items = $input.all();
if (!items.length) return [];
await new Promise(resolve => setTimeout(resolve, 5000));
return items;

const parent = $('Loop Over Structured Batches1').item.json;
const source = String(parent.batch_text || '');
if (!source.trim()) throw new Error(`STRUCTURED_FALLBACK_SOURCE_EMPTY batch=${parent.batch_index}`);
const midpoint = Math.floor(source.length / 2);
const candidates = [
  source.lastIndexOf('\n', midpoint),
  source.indexOf('\n', midpoint),
  source.lastIndexOf('. ', midpoint),
  source.indexOf('. ', midpoint),
].filter(position => position > Math.floor(source.length * 0.3) && position < Math.ceil(source.length * 0.7));
const cut = candidates.length
  ? candidates.sort((a, b) => Math.abs(a - midpoint) - Math.abs(b - midpoint))[0] + 1
  : midpoint;
const halves = [source.slice(0, cut).trim(), source.slice(cut).trim()].filter(Boolean);
if (halves.length < 2) throw new Error(`STRUCTURED_FALLBACK_SPLIT_FAILED batch=${parent.batch_index}`);
return halves.map((batch_text, fallback_index) => ({
  json: {
    ...parent,
    parent_batch_index: parent.batch_index,
    fallback_index,
    fallback_count: halves.length,
    batch_text,
    batch_char_count: batch_text.length,
    structured_fallback: true,
  }
}));

