const ctx = $('Loop Over Structured Fallback Halves1').item.json;
const response = $json?.data ?? $json;
const choice = response?.choices?.[0] || {};
const finishReason = choice.finish_reason ?? null;
const raw = choice?.message?.content ?? response?.output_text ?? '';
function firstObject(value) {
  const text = String(value ?? '').replace(/^\uFEFF/, '').replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
  let start = -1, depth = 0, inString = false, escaped = false;
  for (let index = 0; index < text.length; index++) {
    const char = text[index];
    if (start < 0) { if (char === '{') { start = index; depth = 1; } continue; }
    if (inString) {
      if (escaped) { escaped = false; continue; }
      if (char === '\\') { escaped = true; continue; }
      if (char === '"') inString = false;
      continue;
    }
    if (char === '"') { inString = true; continue; }
    if (char === '{') depth++;
    else if (char === '}' && --depth === 0) return { text: text.slice(start, index + 1), balanced: true };
  }
  return { text: start >= 0 ? text.slice(start) : text, balanced: false };
}
function sanitize(value) {
  let output = '', inString = false, escaped = false;
  for (let index = 0; index < value.length; index++) {
    const char = value[index];
    if (inString) {
      if (escaped) { output += char; escaped = false; continue; }
      if (char === '\\') { output += char; escaped = true; continue; }
      if (char === '"') { output += char; inString = false; continue; }
      const code = char.charCodeAt(0);
      if (code < 32) { output += char === '\n' ? '\\n' : char === '\r' ? '\\r' : char === '\t' ? '\\t' : '\\u' + code.toString(16).padStart(4, '0'); continue; }
      output += char;
      continue;
    }
    if (char === '"') { inString = true; output += char; continue; }
    if (char === ',') {
      let cursor = index + 1;
      while (cursor < value.length && /\s/.test(value[cursor])) cursor++;
      if (value[cursor] === '}' || value[cursor] === ']') continue;
    }
    output += char;
  }
  return output;
}
if (typeof raw !== 'string' && (!raw || typeof raw !== 'object')) throw new Error(`STRUCTURED_FALLBACK_RESPONSE_MISSING batch=${ctx.parent_batch_index}.${ctx.fallback_index}`);
let parsed;
if (typeof raw === 'object') parsed = raw;
else {
  const extracted = firstObject(raw);
  if (finishReason === 'length' || !extracted.balanced) throw new Error(`STRUCTURED_FALLBACK_TRUNCATED batch=${ctx.parent_batch_index}.${ctx.fallback_index} chars=${raw.length} finish_reason=${finishReason ?? 'unknown'}`);
  try { parsed = JSON.parse(extracted.text); }
  catch (firstError) {
    try { parsed = JSON.parse(sanitize(extracted.text)); }
    catch (secondError) { throw new Error(`STRUCTURED_FALLBACK_JSON_INVALID batch=${ctx.parent_batch_index}.${ctx.fallback_index} chars=${raw.length}: ${secondError.message}`); }
  }
}
const writes = Array.isArray(parsed?.writes) ? parsed.writes : [];
return { json: { ...ctx, writes, write_count: writes.length, finish_reason: finishReason } };

const halves = $input.all().map(item => item.json).sort((a, b) => Number(a.fallback_index) - Number(b.fallback_index));
if (!halves.length) throw new Error('STRUCTURED_FALLBACK_MERGE_EMPTY');
const expected = Number(halves[0].fallback_count);
if (halves.length !== expected) throw new Error(`STRUCTURED_FALLBACK_MISSING expected=${expected} actual=${halves.length}`);
for (let index = 0; index < halves.length; index++) {
  if (Number(halves[index].fallback_index) !== index) throw new Error(`STRUCTURED_FALLBACK_ORDER_INVALID expected=${index} actual=${halves[index].fallback_index}`);
}
const parent = $('Loop Over Structured Batches1').item.json;
const writes = halves.flatMap(half => Array.isArray(half.writes) ? half.writes : []);
return [{ json: { ...parent, writes, write_count: writes.length, finish_reason: 'fallback_split_complete', structured_fallback_used: true, fallback_count: halves.length } }];

